let refreshPending=null;
async function renewSession(){if(!refreshPending)refreshPending=fetch('/api/auth/refresh',{method:'POST',cache:'no-store',headers:{'Content-Type':'application/json'},body:'{}'}).then(r=>r.ok).catch(()=>false).finally(()=>refreshPending=null);return refreshPending}
async function api(path,method='GET',data){const options={method,cache:'no-store',headers:method==='GET'?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)};let response=await fetch(path,options);if(response.status===401&&!path.startsWith('/api/auth/')&&await renewSession())response=await fetch(path,options);const value=await response.json();if(!response.ok)throw new Error(t(value.error||'So‘rov bajarlmadi.'));// Any change (menu, restaurant, tables…) makes the next page read a fresh catalog.
if(method!=='GET')state.catalogAt=0;return value;}

function notify(message){$('#toast').textContent=t(message);$('#toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').hidden=true,5500)}
function empty(title,description,symbol='◇'){return `<div class="empty"><div class="empty-symbol">${symbol}</div><h3>${esc(title)}</h3><p>${esc(description)}</p></div>`}
