function syncDrawerTheme(){const light=document.body.dataset.theme==='light',button=$('#drawerTheme');if(!button)return;const icon=light?'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>':'<path d="M20.5 13A8.5 8.5 0 0 1 11 3.5 8.5 8.5 0 1 0 20.5 13Z"/>';button.innerHTML=`<span class="theme-symbol"><svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" aria-hidden="true">${icon}</svg></span><span>${t(light?'Kunduzgi rejim':'Tungi rejim')}</span><span class="theme-switch" aria-hidden="true"><i></i></span>`;button.setAttribute('aria-label',t('Kunduzgi rejim'));button.setAttribute('role','switch');button.setAttribute('aria-checked',String(light));button.onclick=()=>{document.body.dataset.theme=light?'dark':'light';try{localStorage.setItem('rf-theme',document.body.dataset.theme)}catch{}syncDrawerTheme()}}
function profileAvatar(){const name=state.user?.name||'',initials=name.trim().split(/\s+/).slice(0,2).map(part=>Array.from(part)[0]||'').join('').toLocaleUpperCase();return `<span class="profile-avatar" aria-hidden="true">${initials?esc(initials):'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/></svg>'}</span>`}
let orbMounted=false;
// Managers talk to the Admin AI orb; the customer voice robot button is for clients only.
// The Admin AI orb lives only inside the restaurant dashboard; couriers get no assistant at all.
function adminOrb(){const role=state.user?.role,manager=['restaurant_owner','admin'].includes(role),show=manager&&routeName()==='manage';document.body.classList.toggle('rf-manager',manager);document.body.classList.toggle('rf-courier',role==='courier');if(show===orbMounted||!window.RF3DLoad)return;orbMounted=show;window.RF3DLoad().then(api=>show?api.orb.mount({lang:document.documentElement.lang}):api.orb.unmount()).catch(()=>{orbMounted=false})}
function navigation(){
 syncDrawerTheme();adminOrb();// Call AI: the site rings when a booking's confirmation call is open.
if(state.user&&!state.user.needsProfile)window.RFCallAI?.watch();if(!state.user?.needsProfile)window.RFApp?.signedIn(state.user);const route=routeName(),keys=['discover','search','cart','bookings','orders','flowers'];
 if(state.user?.role==='admin')keys.push('admin');if(['restaurant_owner','admin'].includes(state.user?.role))keys.push('manage','camera');else if(state.user?.staff?.length)keys.push('manage');if(state.user?.role==='courier')keys.push('courier');if(['florist','admin'].includes(state.user?.role))keys.push('florist');keys.push('pricing','billing','settings','help');
 const helpRoutes=['help','support','faq','blog'];
 $('#nav').innerHTML=`<a href="${state.user?'#/account':'#/login'}" class="drawer-profile ${route==='account'?'active':''}" ${route==='account'?'aria-current="page"':''}>${profileAvatar()}<span class="profile-copy"><strong>${esc(state.user?.name||t('Kirish'))}</strong><small>${t('Profil')}</small></span><span aria-hidden="true">›</span></a><div class="drawer-links">`+keys.map(id=>{const active=route===id||(id==='help'&&helpRoutes.includes(route));return `<a href="#/${id}" ${['discover','search','cart'].includes(id)?'data-bottom-nav':''} class="${active?'active':''}" ${active?'aria-current="page"':''}><span class="nav-ico" aria-hidden="true">${drawerIcon(id)}</span><span>${id==='help'?t('Yordam markazi'):labels[id]}</span><span aria-hidden="true">›</span></a>`}).join('')+'</div>';
 $('#logout').hidden=!state.user;$('#accountButton').hidden=!!state.user;$('#accountButton').textContent=state.user?'Profil':'Kirish';$('#accountButton').href=state.user?'#/account':'#/login';$('#logout').textContent=t('Chiqish');$('#menuButton').setAttribute('aria-label',t('Menyuni ochish'));$('#closeDrawer').setAttribute('aria-label',t('Yopish'));bindLanguageSelect();
}
// The drawer grows out of the menu button and shrinks back into it (motion.js); Esc takes the same path.
function closeDrawer(){const d=$('#drawer');if(!d.open)return;if(window.RFMotion)RFMotion.close(d).then(()=>d.open&&d.close());else d.close()}
$('#drawer').addEventListener('cancel',e=>{e.preventDefault();closeDrawer()});
$('#menuButton').onclick=e=>openDrawer(e.currentTarget);$('#closeDrawer').onclick=()=>closeDrawer();$('#drawer').addEventListener('close',()=>{$('#menuButton').setAttribute('aria-expanded','false');document.querySelector('.mobile-more')?.setAttribute('aria-expanded','false')});$('#nav').onclick=e=>{if(e.target.closest('a'))closeDrawer()};$('#drawer').onclick=e=>{if(e.target===$('#drawer'))closeDrawer()};
document.addEventListener('click',e=>{const a=e.target.closest('a[href="#/login"],a[href="#/signup"]');if(a&&!['login','signup','forgot','reset','verify'].includes(routeName()))try{sessionStorage.setItem('rf-after-login',location.hash||'#/discover')}catch{}});
$('#logout').onclick=async()=>{try{const source=state.user?.source;await api('/api/auth/logout','POST',{});if(source==='chatgpt'){window.top.location.href='/signout-with-chatgpt?return_to=%2F';return}state.user=null;closeDrawer();location.hash='/discover';render()}catch(e){notify(e.message)}};
function routeName(){return location.hash.replace(/^#\/?/,'').split('/')[0]||(location.pathname==='/admin-login'?'admin-login':'discover')}
function captchaStatus(kind,message){const widget=$('#captchaWidget');if(widget)widget.hidden=kind==='success';const box=$('#captchaStatus');if(!box)return;box.dataset.status=kind;box.innerHTML=`<span class="captcha-indicator" aria-hidden="true">${kind==='success'?'✓':kind==='error'?'!':''}</span><span>${esc(t(message))}</span>`;}
function captchaMount(){
 state.captcha=null;clearTimeout(state.captchaTimer);clearTimeout(state.captchaWatchdog);const root=$('#captcha');if(!state.config.ready||!root)return;
 if(state.widget!==null&&window.turnstile){try{window.turnstile.remove(state.widget)}catch{}state.widget=null}
 const generation=(state.captchaGeneration||0)+1;state.captchaGeneration=generation;
 root.innerHTML='<div id="captchaStatus" class="captcha-status" role="status" aria-live="polite"></div><div id="captchaWidget"></div><button type="button" class="link captcha-retry" id="captchaRetry" hidden>Tekshiruvni qayta boshlash</button>';
 const current=()=>state.captchaGeneration===generation&&$('#captcha')===root;
 const show=(kind,msg)=>{if(current())captchaStatus(kind,msg)};
 const fail=message=>{if(!current())return;state.captcha=null;clearTimeout(state.captchaTimer);clearTimeout(state.captchaWatchdog);show('error',message);$('#captchaRetry').hidden=false;};
 $('#captchaRetry').onclick=()=>{if(!window.turnstile){$('#captchaScript')?.remove();captchaMount()}else resetCaptcha()};
 const watch=()=>{clearTimeout(state.captchaWatchdog);state.captchaWatchdog=setTimeout(()=>fail('Tekshiruv vaqti tugadi. Qayta urinib ko‘ring.'),30000)};state.captchaWatch=watch;watch();
 show('loading','Tekshirilmoqda…');
 const mount=()=>{if(!current())return;try{state.widget=window.turnstile.render('#captchaWidget',{sitekey:state.config.sitekey,theme:'light',size:'flexible',appearance:'always',execution:'render',language:RF_I18N.lang==='uz'?'en':RF_I18N.lang,'response-field':false,retry:'never','refresh-expired':'auto','refresh-timeout':'auto',
 callback:token=>{if(!current()||typeof token!=='string'||!token||token.length>2048)return;clearTimeout(state.captchaWatchdog);state.captcha=token;$('#captchaRetry').hidden=true;show('success',"Tekshiruvdan o'tdi");clearTimeout(state.captchaTimer);state.captchaTimer=setTimeout(()=>{if(current()&&state.captcha===token){state.captcha=null;show('loading','Tekshiruv yangilanmoqda…');resetCaptcha()}},290000)},
 'before-interactive-callback':()=>{if(!current())return;clearTimeout(state.captchaWatchdog);show('interactive','Cloudflare tekshiruvini bajaring.')},
 'after-interactive-callback':()=>{if(current()&&!state.captcha){watch();show('loading','Tekshirilmoqda…')}},
 'expired-callback':()=>{if(!current())return;state.captcha=null;clearTimeout(state.captchaTimer);watch();show('loading','Tekshiruv yangilanmoqda…')},
 'timeout-callback':()=>fail('Tekshiruv vaqti tugadi. Qayta urinib ko‘ring.'),
 'error-callback':code=>{fail('Tekshiruv bajarilmadi. Internetni tekshiring yoki qayta urinib ko‘ring.');if(current()&&/^\d{3,6}$/.test(String(code)))$('#captchaStatus').innerHTML+='<small> ('+esc(String(code))+')</small>';return true},
 'unsupported-callback':()=>fail('Brauzeringizni yangilang yoki boshqa brauzerda oching.')
 })}catch{fail('Tekshiruv yuklanmadi. Qayta urinib ko‘ring.')}};
 if(window.turnstile)mount();else{window.rfCaptchaReady=mount;if(!$('#captchaScript')){const script=document.createElement('script');script.id='captchaScript';script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?onload=rfCaptchaReady&render=explicit';script.async=true;script.onerror=()=>{script.remove();fail('Tekshiruv yuklanmadi. Qayta urinib ko‘ring.')};document.head.append(script)}}
}
function resetCaptcha(){state.captcha=null;clearTimeout(state.captchaTimer);captchaStatus('loading','Tekshiruv yangilanmoqda…');if($('#captchaRetry'))$('#captchaRetry').hidden=true;if(window.turnstile&&state.widget!==null)try{state.captchaWatch?.();window.turnstile.reset(state.widget)}catch{captchaMount()}else captchaMount()}
function captchaDispose(){clearTimeout(state.captchaWatchdog);state.captchaWatch=null;state.captcha=null;state.captchaGeneration=(state.captchaGeneration||0)+1;clearTimeout(state.captchaTimer);if(window.turnstile&&state.widget!==null)try{window.turnstile.remove(state.widget)}catch{}state.widget=null;}
// The catalog is shared by every page: reuse it for a minute and share one request in flight,
// so moving between pages does not wait for the network each time.
let catalogLoad=null;
async function loadCatalog(){if(state.catalog&&Date.now()-(state.catalogAt||0)<10000)return;catalogLoad??=api('/api/catalog').then(d=>{state.catalog=d.restaurants.filter(r=>d.demo_enabled!==false||state.user?.role==='admin'||!r.is_demo);state.menu=d.menu;state.catalogAt=Date.now();document.dispatchEvent(new Event('rf:catalog-ready'))}).finally(()=>{catalogLoad=null});return catalogLoad}
// Plan features of a catalog restaurant ({menu3d,room3d,clientAi,…}); undefined until the catalog is loaded.
window.RFFeatures=id=>state.catalog?.find(r=>r.id===id)?.features;window.RFClientAiAny=()=>state.catalog?state.catalog.some(r=>r.features?.clientAi):undefined;
function rating(r){return Number(r.review_count)>0?`<span class="rating">★ ${Number(r.rating).toFixed(1)}</span> <small>(${r.review_count} ta sharh)</small>`:'<small>Hali baholanmagan</small>'}
let catalogFilter={query:'',cuisine:'',min:'',max:'',service:'all'};
function catalogMatches(r,menu,f){const q=f.query.trim().toLocaleLowerCase(),dishes=menu.filter(m=>m.restaurant_id===r.id&&m.available),restaurantMatch=(r.name+' '+r.cuisine+' '+r.address).toLocaleLowerCase().includes(q),priced=dishes.filter(m=>(f.min===''||m.price>=Number(f.min))&&(f.max===''||m.price<=Number(f.max)));return (!f.cuisine||r.cuisine===f.cuisine)&&(f.service!=='delivery'||r.delivery_enabled)&&(f.service!=='booking'||r.tables>0)&&((f.min===''&&f.max==='')||priced.length>0)&&(!q||restaurantMatch||priced.some(m=>(m.name+' '+m.description+' '+m.category).toLocaleLowerCase().includes(q)))}
function serviceChoices(r){return `<div class="service-choices" role="group" aria-label="Xizmat turi"><button class="quiet" type="button" data-service="delivery" ${r&&!r.delivery_enabled?'disabled':''}>Yetkazib berish</button><button class="quiet" type="button" data-service="pickup">Olib ketish</button><button class="quiet" type="button" data-service="booking" ${r&&!r.tables?'disabled':''}>Stol bron qilish</button></div>`}
function bindServiceChoices(){document.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>{catalogFilter.service=b.dataset.service;document.querySelectorAll('[data-service]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));if($('#restaurantList')){catalogCards();document.querySelectorAll('[data-service]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}else{if(b.dataset.service==='booking'){document.getElementById('openBookingRoom')?.click();return}if(b.dataset.service!=='booking'){state.selectedFulfillment=b.dataset.service;if(state.cart){state.cart.fulfillment=b.dataset.service;saveCart()}}$(b.dataset.service==='booking'?'#bookingPlan':'#orderForm')?.scrollIntoView({behavior:'smooth',block:'start'})}})}
// Paid plan badge: Business is written out, Premium wears a crown. Trial and Start show none.
function planBadge(r){return r.tier==='premium'?`<span class="plan-badge plan-premium" title="Premium"><span aria-hidden="true">👑</span> Premium</span>`:r.tier==='business'?'<span class="plan-badge plan-business">Business</span>':''}
function restaurantCard(r){const demo=!!r.is_demo||r.id.startsWith('rf-demo-');return `<article class="card restaurant-card" data-restaurant-id="${esc(r.id)}"><div class="restaurant-cover">${r.image_url?`<img class="restaurant-photo" src="${esc(r.image_url)}" alt="${esc(r.name)}" loading="lazy" decoding="async" width="640" height="400">`:`<div class="card-top" aria-hidden="true">${esc(r.name[0])}</div>`}${demo?'<span class="card-demo-tag">DEMO</span>':''}${planBadge(r)}<span class="card-cuisine">${esc(r.cuisine||t('Restoran'))}</span></div><div class="card-main"><h3>${esc(r.name)}</h3><p class="card-address">${esc(r.address)}</p><div class="card-rating">${rating(r)}</div>${demo?'<p class="demo-notice">DEMO: sinov restorani va sun’iy reyting.</p>':''}<div class="card-facts"><p><span aria-hidden="true">◷</span> <span>${t('Ish vaqti')}: ${esc(r.hours||t('Restorandan aniqlashtiring'))}</span></p><p><span aria-hidden="true">↗</span> <span>${r.delivery_enabled?`${t('Yetkazib berish')}: ${money(r.delivery_fee)} · ${r.delivery_minutes?`${r.delivery_minutes} ${t('daqiqa (taxminan)')}`:t('Vaqt restorandan aniqlashtiriladi')}`:t('Olib ketish')}</span></p></div><a class="primary" href="#/restaurant/${encodeURIComponent(r.id)}" aria-label="${esc(r.name)} — ${t('Menyu va bron')}">${t('Menyu va bron')} <span aria-hidden="true">↗</span></a></div></article>`}
function catalogCards(){const f=catalogFilter,list=state.catalog.filter(r=>(localStorage.getItem('rf-show-demo')!=='false'||!(r.is_demo||r.id.startsWith('rf-demo-')))&&catalogMatches(r,state.menu,f));$('#restaurantList').innerHTML=list.length?`<div class="grid">${list.map(restaurantCard).join('')}</div>`:empty('Restoran topilmadi','Qidiruv yoki filtrlarni o‘zgartiring.');const q=f.query.trim().toLowerCase();const dishes=q?state.menu.filter(m=>m.available&&list.some(r=>r.id===m.restaurant_id)&&(m.name+' '+m.description+' '+m.category).toLowerCase().includes(q)&&(f.min===''||m.price>=Number(f.min))&&(f.max===''||m.price<=Number(f.max))):[];if(dishes.length)$('#restaurantList').insertAdjacentHTML('beforeend',`<h2 class="results-title">Topilgan taomlar</h2><div class="grid">${dishes.map(m=>`<a class="card" href="#/restaurant/${encodeURIComponent(m.restaurant_id)}">${foodPicture(m)}<div class="card-main"><h3>${esc(m.name)}</h3><p>${money(m.price)} · ${esc(state.catalog.find(r=>r.id===m.restaurant_id).name)}</p></div></a>`).join('')}</div>`);bindFoodImages()}

function renderMarketplaceHome(){
 const list=state.catalog.filter(r=>localStorage.getItem('rf-show-demo')!=='false'||!(r.is_demo||r.id.startsWith('rf-demo-')));
 const real=list.filter(r=>!r.is_demo&&!r.id.startsWith('rf-demo-'));
 const popular=real.filter(r=>Number(r.review_count)>0).sort((a,b)=>Number(b.rating)-Number(a.rating)).slice(0,3);
 const cuisines=new Set(),recommended=list.filter(r=>{const key=r.cuisine||r.id;if(cuisines.has(key))return false;cuisines.add(key);return true}).slice(0,3);
 const cards=rows=>`<div class="grid marketplace-grid">${rows.map(restaurantCard).join('')}</div>`;
 page('Restoranlar',`<section class="market-hero"><div class="hero-copy"><p class="eyebrow">TA’M. DAVRA. XOTIRA.</p><h2>Ajoyib taom.<br><span>Yaxshi davra.</span></h2><p>Keyingi uchrashuvingiz uchun restoran, dasturxoningiz uchun yangi ta’m.</p><div class="hero-actions"><a class="primary" href="#/discover" data-home-explore>Restoranlarni ko‘rish <span aria-hidden="true">↗</span></a></div></div><div class="hero-art" aria-hidden="true"><div class="ambient-orbit"></div><img class="hero-dish" src="/demo-assets/food-grill.jpg" width="480" height="480" alt="" decoding="async"><span class="hero-caption">RESTAURANTFOODS</span></div></section>
 <nav class="home-services" aria-label="${t('Xizmat turi')}"><a class="service-tile" data-home-service="delivery" href="#/search"><span aria-hidden="true">↗</span><strong>Yetkazib berish</strong><span aria-hidden="true">→</span></a></nav>
 <section class="market-section" id="homeRestaurants"><div class="section-heading"><div><p class="eyebrow">SIZNING KEYINGI MANZILINGIZ</p><h2>Restoranlarni kashf eting</h2></div><a class="quiet" href="#/search">Barchasini ko‘rish →</a></div>${list.length?cards(list):empty('Restoranlar hali qo‘shilmagan','Tasdiqlangan restoranlar shu yerda ko‘rinadi.')}</section>
 ${popular.length?`<section class="market-section"><div class="section-heading"><h2>Yuqori baholangan restoranlar</h2></div>${cards(popular)}</section>`:''}
 ${recommended.length?`<section class="market-section"><div class="section-heading"><div><p class="eyebrow">YANGI TA’MLARNI KASHF ETING</p><h2>Har xil ta’b uchun tanlovlar</h2><p>Turli oshxonalardan tanishish uchun tavsiyalar.</p></div></div>${cards(recommended)}</section>`:''}`);
 document.querySelectorAll('[data-home-service]').forEach(link=>link.onclick=()=>{catalogFilter={query:'',cuisine:'',min:'',max:'',service:link.dataset.homeService}});
 const explore=document.querySelector('[data-home-explore]');if(explore)explore.onclick=e=>{e.preventDefault();document.getElementById('homeRestaurants')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})};
 bindFoodImages();
}

async function discover(seq){await loadCatalog();if(seq!==state.seq)return;if(routeName()!=='search'){renderMarketplaceHome();return}page(routeName()==='search'?'Qidiruv':'Dasturxoningizni tanlang.',`${serviceChoices()}<div class="catalog-filters form search-panel"><label>Restoran yoki taom<input id="search" type="search" value="${esc(catalogFilter.query)}" placeholder="Restoran yoki taom"></label><label>Oshxona turi<select id="cuisineFilter"><option value="">Barchasi</option>${[...new Set(state.catalog.map(r=>r.cuisine).filter(Boolean))].sort().map(c=>`<option value="${esc(c)}" ${c===catalogFilter.cuisine?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Eng kam narx<input id="minPrice" type="number" min="0" step="1000" value="${esc(catalogFilter.min)}"></label><label>Eng yuqori narx<input id="maxPrice" type="number" min="0" step="1000" value="${esc(catalogFilter.max)}"></label><button id="clearFilters" type="button" class="quiet">Filtrlarni tozalash</button></div><p>Filtrdagi narx bitta mavjud taom uchun, so‘mda.</p><div id="restaurantList"></div>`);catalogCards();bindServiceChoices();for(const [id,key] of [['search','query'],['cuisineFilter','cuisine'],['minPrice','min'],['maxPrice','max']])$('#'+id).oninput=e=>{catalogFilter[key]=e.target.value;catalogCards()};$('#clearFilters').onclick=()=>{catalogFilter={query:'',cuisine:'',min:'',max:'',service:'all'};discover(seq)};if(routeName()==='search')$('#search').focus()}
function bookingMealSummary(b){let items=[];try{items=JSON.parse(b.preorder_items||'[]')}catch{}return items.length?'<br><strong>'+esc(t('Stol uchun taomlar'))+'</strong>: '+items.map(i=>esc(i.name)+' × '+Number(i.quantity)).join(', ')+' · '+money(b.preorder_total):''}
async function historyPage(kind,seq){if(!state.user){page(labels[kind],empty('Avval akkauntingizga kiring','Shaxsiy bron va buyurtmalaringiz faqat sizga ko‘rinadi.')+'<p><a class="primary" href="#/login">Kirish</a></p>');return}const rows=await api('/api/'+kind);if(seq!==state.seq)return;page(labels[kind],rows.length?`<div class="panel">${rows.map(x=>`<article class="row"><div><h3>${esc(x.restaurant_name)}</h3><span class="badge">${statusName[x.status]||esc(x.status)}</span><p>${kind==='bookings'?`${esc(x.date)} · ${esc(x.slot)}–${esc(bookingEnd(x))} · ${x.guests} kishi · Stol ${x.table_number}${bookingMealSummary(x)}`:`${money(x.total)} · ${x.fulfillment==='delivery'?'Yetkazib berish':'Restorandan olib ketish'}`}</p>${kind==='orders'?`${orderProgress(x)}<p>${JSON.parse(x.items).map(i=>`${esc(i.name)} × ${i.quantity}`).join(', ')}</p><small>To‘lov qabul qilish vaqtida. Buyurtma holati pul to‘langanini bildirmaydi.</small>`:''}</div><div class="row-actions">${kind==='orders'?`<a class="quiet" href="#/tracking/${esc(x.id)}">Manzil va buyurtma →</a>`:`<a class="quiet" href="#/restaurant/${esc(x.restaurant_id)}">Restoran va xarita →</a>`}${kind==='bookings'?`<button class="quiet" data-receipt="${esc(x.id)}">🧾 ${t('Chek')}</button>${['pending','confirmed'].includes(x.status)?`<button class="quiet" data-pass="${esc(x.id)}">🎟 ${t('Chipta')}</button>`:''}`:''}${kind==='bookings'&&x.penalty_amount?`<span class="badge ${x.penalty_status==='paid'?'warn':''}">💳 ${t('Jarima')}: ${money(x.penalty_amount)}${x.penalty_status==='failed'?' · '+t('yechilmadi'):''}</span>`:''}${kind==='bookings'&&['pending','confirmed'].includes(x.status)?(bookingCancellable(x)?`<button class="quiet" data-cancel="${esc(x.id)}">Bekor qilish</button>`:`<span><button class="quiet" disabled aria-describedby="late-${esc(x.id)}">Bekor qilish</button><small class="cancel-blocked" id="late-${esc(x.id)}">${t('Bron vaqtiga 2 soatdan kam qoldi — ilova orqali bekor qilib bo‘lmaydi. Bekor qilish uchun restoranga qo‘ng‘iroq qiling; kelishilgan jarima kartangizdan yechiladi.')}</small></span>`):kind==='orders'&&x.status==='pending'?`<button class="quiet" data-cancel="${esc(x.id)}">Bekor qilish</button>`:''}${x.status==='completed'?`<a class="quiet" href="#/restaurant/${esc(x.restaurant_id)}">Sharh qoldirish</a>`:''}</div></article>`).join('')}</div>`:empty('Hali yozuvlar yo‘q',kind==='bookings'?'Restoran tanlab, tashrif uchun bron yuboring.':'Menyudan taom tanlab, buyurtma yuboring.'));if(kind==='bookings')watchBookingStatus('mine',seq,()=>{notify('Bron holati yangilandi.');render()});document.querySelectorAll('[data-receipt]').forEach(b=>b.onclick=()=>window.RFReceipt?.open(b.dataset.receipt));document.querySelectorAll('[data-pass]').forEach(b=>b.onclick=()=>window.RFReceipt?.open(b.dataset.pass,{mode:'pass'}));document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{try{// Bookings show the penalty (if any) before cancelling.
if(kind==='bookings'&&window.RFCards){if(await window.RFCards.cancelBooking(b.dataset.cancel))render();return}if(!confirm('Bekor qilinsinmi?'))return;await api('/api/'+kind,'PATCH',{id:b.dataset.cancel});render()}catch(e){notify(e.message)}})}
const menuCategories=JSON.parse("[\"Salatlar\", \"Birinchi taomlar\", \"Ikkinchi taomlar\", \"Fastfood\", \"Garnirlar\", \"Gazli ichimliklar\", \"Gazsiz ichimliklar\", \"Sharbatlar\", \"Issiq ichimliklar\", \"Desertlar\", \"Boshqalar\"]");
function menuCategory(m){const value=String(m.category||'').trim();const aliases=JSON.parse("{\"salatlar\": \"Salatlar\", \"salad\": \"Salatlar\", \"salads\": \"Salatlar\", \"салаты\": \"Salatlar\", \"salat\": \"Salatlar\", \"salat / desert\": \"Salatlar\", \"sho‘rvalar\": \"Birinchi taomlar\", \"soup\": \"Birinchi taomlar\", \"soups\": \"Birinchi taomlar\", \"супы\": \"Birinchi taomlar\", \"sho‘rva\": \"Birinchi taomlar\", \"asosiy taomlar\": \"Ikkinchi taomlar\", \"main\": \"Ikkinchi taomlar\", \"main dishes\": \"Ikkinchi taomlar\", \"основные блюда\": \"Ikkinchi taomlar\", \"asosiy taom\": \"Ikkinchi taomlar\", \"fastfood\": \"Fastfood\", \"fast food\": \"Fastfood\", \"фастфуд\": \"Fastfood\", \"garnirlar\": \"Garnirlar\", \"garnir\": \"Garnirlar\", \"sides\": \"Garnirlar\", \"гарниры\": \"Garnirlar\", \"gazli ichimliklar\": \"Gazli ichimliklar\", \"carbonated drinks\": \"Gazli ichimliklar\", \"soft drinks\": \"Gazli ichimliklar\", \"газированные напитки\": \"Gazli ichimliklar\", \"gazsiz ichimliklar\": \"Gazsiz ichimliklar\", \"still drinks\": \"Gazsiz ichimliklar\", \"негазированные напитки\": \"Gazsiz ichimliklar\", \"issiq ichimliklar\": \"Issiq ichimliklar\", \"hot drinks\": \"Issiq ichimliklar\", \"горячие напитки\": \"Issiq ichimliklar\", \"desertlar\": \"Desertlar\", \"desert\": \"Desertlar\", \"dessert\": \"Desertlar\", \"desserts\": \"Desertlar\", \"десерты\": \"Desertlar\", \"shirinlik\": \"Desertlar\", \"boshqalar\": \"Boshqalar\", \"other\": \"Boshqalar\", \"другое\": \"Boshqalar\", \"ichimlik\": \"Boshqalar\", \"ichimliklar\": \"Boshqalar\", \"sharbatlar\": \"Sharbatlar\", \"sharbat\": \"Sharbatlar\", \"sok\": \"Sharbatlar\", \"juice\": \"Sharbatlar\", \"juices\": \"Sharbatlar\", \"сок\": \"Sharbatlar\", \"соки\": \"Sharbatlar\"}");return aliases[value.toLocaleLowerCase()]||value||menuCategories[menuCategories.length-1]}
function renderMenuGroups(menu,restaurant=null){
 const groups=new Map();for(const m of menu){const category=menuCategory(m);if(!groups.has(category))groups.set(category,[]);groups.get(category).push(m)}
 const keys=[...groups.keys()].sort((a,b)=>{const ai=menuCategories.indexOf(a),bi=menuCategories.indexOf(b);return (ai<0?99:ai)-(bi<0?99:bi)});let leaf=0;
 const dish=m=>`<article class="food-card" data-dish="${esc(m.id)}">${foodPicture(m)}<div class="food-info"><h3>${esc(m.name)}</h3>${m.category?`<span class="badge">${esc(t(menuCategory(m)))}</span>`:''}<p>${esc(m.description||'')}</p><p>${money(m.price)}</p><span class="badge">${m.available?'Hozir mavjud':'Hozir mavjud emas'}</span>${m.ingredients?`<small>Tarkibi: ${esc(m.ingredients)}</small><br>`:''}<small>Allergenlar: ${esc(m.allergens||'Restorandan aniqlashtiring')}</small></div><label class="menu-quantity"><span class="muted">Soni</span><span class="quantity-stepper"><button type="button" data-qty-step="-1" aria-label="${esc(t('Kamaytirish'))}" ${m.available?'':'disabled'}>−</button><input class="qty" name="${esc(m.id)}" type="number" min="0" max="20" value="${m.available?1:0}" ${m.available?'':'disabled'} aria-label="${esc(m.name)} soni"><button type="button" data-qty-step="1" aria-label="${esc(t('Ko‘paytirish'))}" ${m.available?'':'disabled'}>+</button></span></label><button type="button" class="primary menu-add-cart" data-menu-add="${esc(m.id)}" ${m.available?'':'disabled'}><span aria-hidden="true">＋</span> Savatga qo‘shish</button></article>`;
 const categories=`<nav class="menu-categories" aria-label="${esc(t('Menyu kategoriyalari'))}"><button type="button" class="quiet active" data-menu-category="all" aria-pressed="true">${t('Barchasi')}</button>${keys.map((k,i)=>`<button type="button" class="quiet" data-menu-category="menuCategory${i}" aria-pressed="false">${esc(t(k))} <small>${groups.get(k).length}</small></button>`).join('')}</nav>`;
 // Business/Premium restaurants get the full-screen 3D book; the launcher stays hidden until WebGL is confirmed.
 const launcher=restaurant?.features?.menu3d?`<button type="button" class="menu-3d-launch neon" data-menu-3d-open hidden><span class="menu-3d-launch-icon" aria-hidden="true">📖</span><span><b>Interaktiv 3D menyu</b><small>Varaqlab ko‘ring</small></span><span class="menu-3d-launch-arrow" aria-hidden="true">↗</span></button>`:'';
 return launcher+categories+keys.map((k,i)=>`<section class="menu-category" id="menuCategory${i}"><h3>${esc(t(k))}</h3><div class="rows">${groups.get(k).map(dish).join('')}</div></section>`).join('');
}
function bindMenuCategories(){const book=typeof window!=='undefined'&&window.RFMenuBook;document.querySelectorAll('[data-menu-book]').forEach(root=>book?.bind(root));document.querySelectorAll('[data-menu-category]').forEach(button=>button.onclick=()=>{const key=button.dataset.menuCategory;if(book&&button.closest('[data-menu-book]')){book.select(button.closest('[data-menu-book]'),key);return}document.querySelectorAll('.menu-category').forEach(section=>section.hidden=key!=='all'&&section.id!==key);document.querySelectorAll('[data-menu-category]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))})});document.querySelectorAll('[data-qty-step]').forEach(button=>button.onclick=()=>{const input=button.closest('.quantity-stepper').querySelector('input');if(input.disabled)return;input.value=Math.max(0,Math.min(20,(Number(input.value)||0)+Number(button.dataset.qtyStep)));input.dispatchEvent(new Event('input',{bubbles:true}))})}
// Full-screen WebGL menu (components/menu-book-3d), loaded on demand through public/rf-3d-loader.js.
function menuBookData(r,menu){const groups=new Map();for(const m of menu){const category=menuCategory(m);if(!groups.has(category))groups.set(category,[]);groups.get(category).push(m)}
 const keys=[...groups.keys()].sort((a,b)=>{const ai=menuCategories.indexOf(a),bi=menuCategories.indexOf(b);return (ai<0?99:ai)-(bi<0?99:bi)});
 return {restaurantName:r.name,chapters:keys.map((k,i)=>({key:'menuCategory'+i,title:t(k),dishes:groups.get(k).map(m=>({id:m.id,name:m.name,description:m.description||'',ingredients:m.ingredients||'',price:money(m.price),image:m.image_url||null,available:Boolean(m.available)}))}))}}
function bindMenuBook3D(r,menu){const button=document.querySelector('[data-menu-3d-open]'),form=button?.closest('form');if(!button||!form||!menu.length)return;const probe=document.createElement('canvas');try{if(!(probe.getContext('webgl2')||probe.getContext('webgl')))return}catch{return}if(matchMedia('(hover:hover) and (prefers-reduced-motion:no-preference)').matches){button.onpointermove=e=>{const b=button.getBoundingClientRect(),x=(e.clientX-b.left)/b.width-.5,y=(e.clientY-b.top)/b.height-.5;button.style.setProperty('--rx',(-y*10).toFixed(2)+'deg');button.style.setProperty('--ry',(x*14).toFixed(2)+'deg');button.style.setProperty('--gx',((x+.5)*100).toFixed(1)+'%')};button.onpointerleave=()=>{for(const k of ['--rx','--ry','--gx'])button.style.removeProperty(k)}}
 // Adding goes through the existing button handler so cart validation, confirmation and flight effects stay identical.
 const onAddToCart=(dish,quantity)=>{const input=form.elements.namedItem(dish.id),add=form.querySelector('[data-menu-add="'+CSS.escape(dish.id)+'"]');if(!input||!add)return false;const before=JSON.stringify(readCart());input.value=String(quantity);add.click();return JSON.stringify(readCart())!==before};
 // origin: the element the full-screen book grows out of and shrinks back into.
 // The 3D bundle loads only on the first tap (no background preload: on phones it froze the page).
 const open=(revealDishId,origin=button)=>{if(button.getAttribute('aria-busy')==='true')return;button.setAttribute('aria-busy','true');return window.RF3DLoad?.().then(api=>{if(form.isConnected)api.fullscreenMenu.open({data:menuBookData(r,menu),lang:document.documentElement.lang,onAddToCart,revealDishId,origin,onClose:()=>button.focus()})}).catch(()=>notify('3D menyuni ochib bo‘lmadi.')).finally(()=>button.removeAttribute('aria-busy'))};
 button.hidden=false;button.onclick=()=>open();button.onpointerdown=()=>{button.onpointerdown=null;window.RF3DLoad?.().catch(()=>{})};
 // Business/Premium: the 3D book is the menu. The plain list stays in the page (hidden) so cart
 // validation and the add buttons keep working; it shows again only if WebGL is missing.
 form.classList.add('menu-3d-only');
 // Tapping a dish photo or name opens the 3D book on that dish, growing out of its card.
 form.addEventListener('click',e=>{const card=e.target.closest('.food-card[data-dish]');if(!card||e.target.closest('button,input,select,a,label,textarea')||!e.target.closest('.food-image,h3'))return;open(card.dataset.dish,card)});
 // The AI guide reveals dishes: open the 3D book on that page, or scroll the 2D list.
 const legacy=window.RFMenuBook;if(legacy&&!legacy.reveal3d){const reveal=legacy.reveal;legacy.reveal3d=true;legacy.reveal=(target,itemId)=>{const launch=target?.querySelector?.('[data-menu-3d-open]:not([hidden])');if(launch){revealDish(target,itemId);return}reveal(target,itemId)}}window.RFMenuBook3DOpen=open;
}
function revealDish(form,itemId){const card=form?.elements?.namedItem?.(itemId)?.closest('.food-card');if(!card)return;card.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});card.classList.add('food-card-highlight');setTimeout(()=>card.classList.remove('food-card-highlight'),2200)}

async function restaurant(id,seq){await loadCatalog();const r=state.catalog.find(x=>x.id===id);if(seq!==state.seq)return;if(!r){page('Restoran',empty('Restoran mavjud emas','U vaqtincha yopilgan yoki hali katalogga qo‘shilmagan.'));return}const menu=state.menu.filter(m=>m.restaurant_id===id);page(r.name,`${r.id.startsWith('rf-demo-')?'<p class="notice">DEMO: haqiqiy xizmat ko‘rsatilmaydi. Buyurtma va bronlar faqat sinov uchun.</p>':''}<a class="link back" href="#/discover">← Restoranlar</a>${planBadge(r)}<p>${esc(r.description)}</p><p>${esc(r.address)} · <a href="tel:${esc(r.phone)}">${esc(r.phone)}</a></p><p>${rating(r)}</p>${r.image_url?`<img class="restaurant-hero" src="${esc(r.image_url)}" alt="${esc(r.name)}" referrerpolicy="no-referrer">`:''}<p>Ish vaqti: ${esc(r.hours||'Restorandan aniqlashtiring')}</p>${mapCard(r.latitude,r.longitude,r.address)}<section class="menu-purpose"><p class="eyebrow">${t('Buyurtma maqsadi')}</p>${serviceChoices(r)}<p>${t('Stolda ovqatlanish uchun avval stolni tanlang. Olib ketish va yetkazish uchun menyudan savatga qo‘shing.')}</p></section><div class="split"><div><section class="panel"><h2>Menyu</h2>${menu.length?`<form id="orderForm"><div class="rows">${renderMenuGroups(menu,r)}</div><p id="orderTotal">Jami: 0 so‘m</p><div class="form"><label>TELEFON<input id="orderPhone" type="tel" placeholder="+998901234567" pattern="\\+998[0-9]{9}" required></label><label>BUYURTMA TURI<select id="fulfillment"><option value="pickup">Restorandan olib ketish</option>${r.delivery_enabled?`<option value="delivery">Yetkazib berish (+${money(r.delivery_fee)})</option>`:''}</select></label><div id="deliveryFields" hidden>${coordinateFields('delivery')}<label>UY, PODYEZD, MO‘LJAL (IXTIYORIY)<input id="deliveryAddress" maxlength="300" placeholder="Ko‘cha, uy, xonadon va mo‘ljal"></label></div><p class="notice">Buyurtma restoran tomonidan tasdiqlanadi. To‘lov qabul qilish vaqtida; onlayn to‘lov hozircha ulanmagan.</p><button class="primary">Buyurtma yuborish</button><p id="orderMessage" class="form-message" role="status"></p></div></form>`:empty('Menyu hali kiritilmagan','Taomlar va haqiqiy narxlar restoran tomonidan qo‘shiladi.')}</section><section class="panel" id="reviews"><h2>Xaridorlar sharhlari</h2><p>Sharhlar yuklanmoqda…</p></section></div><section class="panel booking-panel" id="bookingPlan"><h2>Stolni xaritadan tanlang</h2><p>Joylar yuklanmoqda…</p></section></div>`);
 if(r.is_demo||r.id.startsWith('rf-demo-')){let gallery=[];try{gallery=JSON.parse(r.gallery||'[]')}catch{}const plan=$('#bookingPlan')?.closest('.split');if(plan&&gallery.length)plan.insertAdjacentHTML('beforebegin','<div class="demo-gallery">'+gallery.filter(u=>/^\/demo-assets\/[a-z-]+\.jpg$/.test(u)).map(u=>'<img loading="lazy" src="'+esc(u)+'" alt="DEMO — illustrative interior">').join('')+'</div><p class="muted">DEMO · Illustrative photos / Tasviriy rasmlar / Иллюстративные фото</p>');document.querySelectorAll('[data-add-cart]').forEach(b=>{b.disabled=true;b.textContent='DEMO'});}
bindFoodImages();bindMenuCart(r,menu);bindMenuCategories();bindMenuBook3D(r,menu);bindServiceChoices();
 bindCoordinateButtons();await bookingPlan(id,r,seq);await reviews(id,seq);
}
async function reviews(id,seq){const d=await api('/api/reviews?restaurantId='+encodeURIComponent(id));if(seq!==state.seq||!$('#reviews'))return;$('#reviews').innerHTML=`<h2>Xaridorlar sharhlari</h2><p class="rating">${d.summary.count?`★ ${Number(d.summary.average).toFixed(1)} / 5 · ${d.summary.count} ta baho`:'Hali baho yo‘q'}</p>${d.reviews.map(v=>`<article class="review"><strong>${esc(v.name)}</strong> <span class="rating" aria-label="5 dan ${v.stars}">${'★'.repeat(v.stars)}${'☆'.repeat(5-v.stars)}</span><p>${esc(v.comment)}</p><small>${esc(v.updated_at.slice(0,10))} · ${v.is_demo?'Demo sharh':'Tasdiqlangan xaridor'}</small></article>`).join('')}${d.eligible?`<h3 style="margin-top:25px">${d.mine?'Bahoyingizni yangilang':'Sizning fikringiz'}</h3><form id="reviewForm" class="form"><fieldset class="stars"><legend>1 dan 5 gacha baholang</legend>${[1,2,3,4,5].map(n=>`<label class="star-option"><input type="radio" name="stars" value="${n}" ${d.mine?.stars===n?'checked':''} required aria-label="${n} yulduz">${n}★</label>`).join('')}</fieldset><label>SHARHINGIZ<textarea name="comment" minlength="3" maxlength="1000" required placeholder="Taom, xizmat va taassurotlaringiz haqida yozing">${esc(d.mine?.comment||'')}</textarea></label><button class="primary">${d.mine?'Sharhni yangilash':'Sharhni yuborish'}</button>${d.mine?'<button class="quiet" type="button" id="deleteReview">Sharhimni o‘chirish</button>':''}<p id="reviewMessage" class="form-message" role="status"></p></form>`:'<p class="notice">Shu restorandagi bron yoki buyurtmangiz yakunlangach, xaridor sifatida 1–5 yulduzli baho va sharh qoldirishingiz mumkin.</p>'}`;
 if($('#reviewForm'))$('#reviewForm').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button.primary'),b=Object.fromEntries(new FormData(e.currentTarget));button.disabled=true;try{await api('/api/reviews','POST',{restaurantId:id,stars:Number(b.stars),comment:b.comment});notify('Sharhingiz saqlandi.');await reviews(id,seq)}catch(e){$('#reviewMessage').textContent=e.message;button.disabled=false}};
 if($('#deleteReview'))$('#deleteReview').onclick=async()=>{if(!confirm('Sharhingiz o‘chirilsinmi?'))return;try{await api('/api/reviews','DELETE',{restaurantId:id});await reviews(id,seq)}catch(e){notify(e.message)}};
}
// Telegram (free alternative to SMS): a one-time deep link opens the bot, the customer shares their
// own contact there, the bot sends a 6-digit code at once and the number is verified only after
// that code is typed here. Codes and booking updates later go to the same chat. The page polls
// /api/me while the bot flow is open.
function telegramBlock(){const tg=state.user?.telegram;if(!tg?.available)return '';
 const head=`<div class="telegram-connect" id="telegramConnect"><h3>Telegram</h3>`,foot=`<p class="muted" role="status" data-tg-message></p></div>`;
 if(!tg.linked)return head+`<p class="muted">${t('Raqamingizni bepul tasdiqlang: bot “📱 Raqamni yuborish” tugmasini so‘raydi va darhol tasdiqlash kodini yuboradi.')}</p><button type="button" class="primary telegram-button" data-tg-link>📲 ${t('Telegram orqali tasdiqlash')}</button>`+foot;
 if(!tg.phone)return head+`<p class="notice">${t('Botda “📱 Raqamni yuborish” tugmasini bosing.')}</p><button type="button" class="quiet" data-tg-unlink>${t('Telegram’ni uzish')}</button>`+foot;
 if(!tg.verified)return head+`<form class="form telegram-code" data-tg-code><p>${t('Kod Telegram’ga yuborildi')}: <b>${esc(tg.phone)}</b></p><label>${t('TASDIQLASH KODI')}<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" placeholder="••••••" required></label><div class="contact-phone-actions"><button class="primary" type="submit">${t('Tasdiqlash')}</button><button type="button" class="quiet" data-tg-resend>${t('Kodni qayta yuborish')}</button></div></form>`+foot;
 return head+`<p>✅ ${t('Telegram ulangan.')} <b>${esc(tg.phone)}</b></p><p class="muted">${t('Tasdiqlash kodlari va bron xabarlari Telegram’ga keladi.')}</p><button type="button" class="quiet" data-tg-unlink>${t('Telegram’ni uzish')}</button>`+foot}
let telegramPoll=0;
function bindTelegram(done){const box=$('#telegramConnect');if(!box)return;const say=m=>{const el=box.querySelector('[data-tg-message]');if(el)el.textContent=m};clearInterval(telegramPoll);
 const link=box.querySelector('[data-tg-link]'),unlink=box.querySelector('[data-tg-unlink]'),codeForm=box.querySelector('[data-tg-code]'),resend=box.querySelector('[data-tg-resend]');
 const refresh=me=>{Object.assign(state.user,me);done(me)};
 // Waits for the contact shared in the bot (then the code input appears).
 const watch=()=>{const until=Date.now()+15*60000;clearInterval(telegramPoll);telegramPoll=setInterval(async()=>{if(!document.body.contains(box)||Date.now()>until){clearInterval(telegramPoll);return}if(document.visibilityState==='hidden')return;try{const me=(await api('/api/me')).user;if(me.telegram?.linked&&me.telegram.phone){clearInterval(telegramPoll);refresh(me)}}catch{}},2500)};
 if(link)link.onclick=async()=>{// The tab is opened before the request so popup blockers allow it.
  const tab=window.open('','_blank');link.disabled=true;try{const r=await api('/api/profile','POST',{action:'telegram-link'});if(tab)tab.location.href=r.url;else location.href=r.url;say(t('Telegram’da “Start”, keyin “📱 Raqamni yuborish” tugmasini bosing. Kod kelgach shu yerga kiriting.'));watch()}catch(e){tab?.close();say(e.message)}finally{link.disabled=false}};
 if(unlink)unlink.onclick=async()=>{unlink.disabled=true;try{await api('/api/profile','POST',{action:'telegram-unlink'});refresh({telegram:{...state.user.telegram,linked:false,phone:'',verified:false,otpId:null}})}catch(e){say(e.message);unlink.disabled=false}};
 let otpId=state.user?.telegram?.otpId||null;
 if(resend)resend.onclick=async()=>{resend.disabled=true;try{const r=await api('/api/profile','POST',{action:'contact-otp',phone:state.user.telegram.phone});otpId=r.id;say(t('Kod Telegram’ga yuborildi.'))}catch(e){say(e.message)}finally{setTimeout(()=>{resend.disabled=false},30000)}};
 if(codeForm)codeForm.onsubmit=async e=>{e.preventDefault();const code=codeForm.elements.code.value.trim(),btn=codeForm.querySelector('button[type=submit]');if(!/^\d{6}$/.test(code)){say(t('6 xonali kodni kiriting.'));return}if(!otpId){say(t('Kod eskirgan. Yangi kod oling.'));return}btn.disabled=true;try{const r=await api('/api/profile','POST',{action:'contact-verify',phone:state.user.telegram.phone,otpId,code});if(!r.verified)throw new Error(t('Kod noto‘g‘ri.'));const me=(await api('/api/me')).user;notify(t('Raqam Telegram orqali tasdiqlandi.'));refresh(me)}catch(err){say(err.message);btn.disabled=false}};
 if(state.user?.telegram?.linked&&!state.user.telegram.phone)watch()}
function account(){if(!state.user){location.hash='/login';return}page('Profil',`<div class="panel compact profile-panel"><div class="profile-heading">${profileAvatar()}<div><h3>${esc(state.user.name)}</h3><p>${esc(state.user.email||state.user.phone)}</p></div></div><p>${state.user.emailVerified?'Email tasdiqlangan.':'Telefon tasdiqlangan.'} <strong>${roleLabel(state.user.role)}</strong></p><nav class="profile-shortcuts" aria-label="${esc(t('Shaxsiy bo‘limlar'))}"><a class="quiet" href="#/bookings"><span aria-hidden="true">◷</span>${t('Bronlarim')}<span aria-hidden="true">↗</span></a><a class="quiet" href="#/orders"><span aria-hidden="true">▤</span>${t('Buyurtmalarim')}<span aria-hidden="true">↗</span></a></nav><div class="separator"></div><h3>Aloqa raqami</h3><form id="contactPhoneForm" class="form contact-phone-form"><label>TELEFON<input name="contactPhone" type="tel" inputmode="tel" autocomplete="tel" maxlength="22" placeholder="+998 XX XXX XX XX" value="${esc(state.user.contactPhone||'')}"></label><p class="muted">${state.user.contactPhone?(state.user.contactPhoneVerified?'✓ '+t('Raqam tasdiqlangan.'):t('Raqam hali tasdiqlanmagan.')):''}</p>${state.user.smsVerification&&!state.user.smsCodes&&!state.user.contactPhoneVerified?`<p class="notice">${t('Raqamni pastdagi Telegram tugmasi orqali bepul tasdiqlang.')}</p>`:''}${state.user.smsVerification&&state.user.smsCodes?`<label id="contactCodeRow" hidden>SMS KOD<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" placeholder="••••••"></label>`:''}<div class="contact-phone-actions">${state.user.smsVerification&&!state.user.smsCodes?'':`<button class="primary" type="submit">${state.user.smsVerification?t('Kod olish'):t('Saqlash')}</button>`}${['customer','courier'].includes(state.user.role)?'':'<button class="quiet" type="button" id="removeContactPhone">Raqamni o‘chirish</button>'}</div><p id="contactPhoneMessage" role="status"></p></form><form id="birthForm" class="form inline-form"><label>${t('TUG‘ILGAN SANA')}<input name="birthDate" type="date" max="${new Date().toISOString().slice(0,10)}" value="${esc(state.user.birthDate||'')}"></label><button class="quiet">${t('Saqlash')}</button></form><p class="muted">🎂 ${t('Tug‘ilgan kuningizdan oldin siz borgan restoranlar Telegram orqali maxsus chegirma promokodini yuborishi mumkin.')}</p>${telegramBlock()}<section class="card-section" id="cardSection" hidden></section>${languageSelect()}<a class="primary" href="#${homeFor(state.user)}">Panelni ochish →</a>${state.user.email?'<div class="separator"></div><h3>Parolni o‘zgartirish</h3><p>Emailingizga kelgan kod va yangi parol talab qilinadi.</p><a class="quiet" id="changePassword" href="#/forgot">Tasdiqlash kodi bilan o‘zgartirish</a>':'<p>Telefon bilan kirishda har safar SMS kodi ishlatiladi.</p>'}${state.user.role==='customer'?'<div class="separator"></div><h3>Hamkorlik uchun ariza</h3><p>Restoran egasi, kuryer yoki gulchi sifatida ishlash uchun administrator tasdig‘i kerak. Tasdiqlanmaguncha akkaunt mijoz bo‘lib qoladi.</p><form id="accessRequest" class="form"><label>FAOLIYAT<select name="role"><option value="restaurant_owner">Restoran egasi</option><option value="courier">Kuryer</option><option value="florist">Gulchi (gullar)</option></select></label><label>MA’LUMOT<textarea name="note" minlength="5" maxlength="1000" required></textarea></label><button class="quiet">Ariza yuborish</button></form>':''}</div>`);bindLanguageSelect();bindTelegram(()=>account());window.RFCards?.mountProfile($('#cardSection'));$('#birthForm').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');b.disabled=true;try{const v=e.currentTarget.elements.birthDate.value;await api('/api/profile','POST',{action:'birth-date',birthDate:v});state.user.birthDate=v;notify('✓ '+t('Saqlandi'))}catch(err){notify(err.message)}finally{b.disabled=false}};const phoneForm=$('#contactPhoneForm'),phoneInput=phoneForm.elements.contactPhone;phoneInput.oninput=()=>{let v=phoneInput.value.replace(/\D/g,'');if(v.startsWith('998'))v=v.slice(3);v=v.slice(0,9);phoneInput.value=v?'+998 '+[v.slice(0,2),v.slice(2,5),v.slice(5,7),v.slice(7,9)].filter(Boolean).join(' '):''};const phoneMsg=m=>{$('#contactPhoneMessage').textContent=m},submit=phoneForm.querySelector('button[type=submit]')||document.createElement('button');let phoneOtp=null;
 const savePhone=async value=>{const buttons=phoneForm.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);try{const result=await api('/api/profile','POST',{action:'contact-phone',phone:value});state.user.contactPhone=result.contactPhone;phoneInput.value=result.contactPhone;phoneMsg(t('Aloqa raqami saqlandi.'))}catch(e){phoneMsg(e.message)}finally{buttons.forEach(b=>b.disabled=false)}};
 // With SMS connected a new number is saved only after its code: first "Get code", then "Confirm".
 const otpStep=async()=>{const phone=phoneInput.value.replace(/[ ()-]/g,'');if(!/^\+998\d{9}$/.test(phone)){phoneMsg(t('Telefon: +998 va 9 ta raqam.'));return}submit.disabled=true;try{if(!phoneOtp||phoneOtp.phone!==phone){phoneOtp={...await api('/api/profile','POST',{action:'contact-otp',phone}),phone};$('#contactCodeRow').hidden=false;submit.textContent=t('Tasdiqlash');phoneMsg(phoneOtp.channel==='telegram'?t('Kod Telegram’ga yuborildi.'):t('SMS kod yuborildi.'));phoneForm.elements.code.focus();return}const code=phoneForm.elements.code.value.trim();if(!/^\d{6}$/.test(code)){phoneMsg(t('SMS kodni kiriting.'));return}const r=await api('/api/profile','POST',{action:'contact-verify',phone,otpId:phoneOtp.id,code});state.user=(await api('/api/me')).user;phoneMsg(r.verified?t('Raqam tasdiqlandi.'):t('Aloqa raqami saqlandi.'));account()}catch(e){phoneMsg(e.message)}finally{submit.disabled=false}};
 phoneInput.addEventListener('input',()=>{if(phoneOtp&&phoneOtp.phone!==phoneInput.value.replace(/[ ()-]/g,'')){phoneOtp=null;if($('#contactCodeRow'))$('#contactCodeRow').hidden=true;submit.textContent=t('Kod olish')}});
 phoneForm.onsubmit=e=>{e.preventDefault();if(state.user.smsVerification&&!state.user.smsCodes){phoneMsg(t('Raqamni pastdagi Telegram tugmasi orqali bepul tasdiqlang.'));return}state.user.smsVerification?otpStep():savePhone(phoneInput.value)};if($('#removeContactPhone'))$('#removeContactPhone').onclick=()=>savePhone('');if($('#changePassword'))$('#changePassword').onclick=()=>{state.authEmail=state.user.email;state.authMode='change'};if($('#accessRequest'))$('#accessRequest').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');b.disabled=true;try{await api('/api/profile','POST',{action:'request-access',...Object.fromEntries(new FormData(e.currentTarget))});notify('Ariza yuborildi. Administrator ko‘rib chiqadi.')}catch(err){notify(err.message)}finally{b.disabled=false}};}
// Admin: Telegram bot status and the one-time webhook registration (independent of restaurants).
async function telegramAdmin(seq){const host=$('#telegramAdmin');if(!host)return;let s;try{s=await api('/api/manage','POST',{action:'telegram_status'})}catch(e){host.innerHTML=`<h3>Telegram bot</h3><p class="form-message">${esc(e.message)}</p>`;return}if(seq!==state.seq)return;
 const ok=v=>v?'✅':'❌',expected=location.origin+'/api/telegram/webhook',hooked=s.webhook===expected;
 host.innerHTML=`<h3>Telegram bot</h3><ul class="telegram-checks"><li>${ok(s.token)} TELEGRAM_BOT_TOKEN${s.token&&!s.reachable?' — '+t('token noto‘g‘ri yoki Telegram javob bermadi'):''}</li><li>${ok(s.username)} TELEGRAM_BOT_USERNAME${s.username?' — @'+esc(s.username):''}</li><li>${ok(s.secret)} TELEGRAM_WEBHOOK_SECRET</li><li>${ok(hooked)} Webhook${s.webhook&&!hooked?' — '+esc(s.webhook):''}${s.pending?' · '+t('kutilayotgan')+': '+s.pending:''}</li></ul>${s.lastError?`<p class="notice">${t('Oxirgi xato')}: ${esc(s.lastError)}</p>`:''}${s.token&&s.secret?`<button type="button" class="primary" id="tgWebhookAdmin">${hooked?t('Webhookni qayta yangilash'):t('Webhookni yangilash')}</button>`:`<p class="muted">${t('Cloudflare → Settings → Variables: yetishmayotgan qiymatlarni qo‘shing va Deploy qiling.')}</p>`}${s.username?` <a class="quiet" href="https://t.me/${encodeURIComponent(s.username)}" target="_blank" rel="noopener">${t('Botni ochish')}</a>`:''}<h4>📞 Call AI</h4><p class="muted">${t('Avtomatik tekshiruv har 5 daqiqada ishlaydi: Premium restoranlarda bron vaqtiga 2 soat qolganda mijozga qo‘ng‘iroq qilinadi.')}</p><button type="button" class="quiet" id="callAiRun">📞 ${t('Call AI ni hozir sinab ko‘rish')}</button><p role="status" class="form-message" id="tgWebhookMsg"></p>`;
 if($('#callAiRun'))$('#callAiRun').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{const r=await api('/api/manage','POST',{action:'call_ai_run'});notify('📞 Call AI: '+r.called+' '+t('ta qo‘ng‘iroq')+', '+r.noAnswer+' '+t('ta javobsiz'))}catch(err){notify(err.message)}finally{b.disabled=false}};
 const btn=$('#tgWebhookAdmin');if(btn)btn.onclick=async()=>{btn.disabled=true;try{await api('/api/manage','POST',{action:'telegram_webhook'});notify(t('Telegram webhook yangilandi.'));telegramAdmin(seq)}catch(e){$('#tgWebhookMsg').textContent=e.message;btn.disabled=false}}}
// AI status for the site administrator: GPT-6 Luna (customer robot, Call AI, Admin AI) and GPT-6.1 Sol
// (business analytics) with their backups, the reserve engine, and the OpenAI key update. The key is
// checked by OpenAI before it is saved and never comes back to the browser (only its last 4 characters).
async function aiAdmin(seq){const box=$('#aiAdmin');if(!box)return;box.innerHTML=`<h3>🤖 ${t('AI holati')}</h3><p class="muted">…</p>`;let d;try{d=await api('/api/admin/ai')}catch(e){if(seq===state.seq&&$('#aiAdmin'))box.innerHTML=`<h3>🤖 ${t('AI holati')}</h3><p class="notice">${esc(e.message)}</p>`;return}if(seq!==state.seq||!$('#aiAdmin'))return;
 const row=(name,role,m)=>`<div class="ai-model"><div><b>${name}</b><small>${role}</small></div><span class="badge ${m.active?'ok':'warn'}">${m.active?esc(m.active)+(m.active===m.backup?' · '+t('zaxira'):''):t('ishlamayapti')}</span></div>`;
 const key=d.key,keyLine=key.valid===true?`✅ ${t('Kalit faol')} (${key.source==='admin'?t('admin panelda saqlangan')+(key.stored.last4?' …'+esc(key.stored.last4):''):t('Supabase secret')})`:key.valid===false?`❌ ${t('Kalit noto‘g‘ri yoki o‘chirilgan')}`:`⚠️ ${t('Kalit holatini tekshirib bo‘lmadi')}`;
 box.innerHTML=`<h3>🤖 ${t('AI holati')}</h3><div class="ai-models">${row('GPT-6 Luna',t('Mijoz AI roboti, Call AI, Admin AI'),d.luna)}${row('GPT-6.1 Sol',t('Biznes analitika va moliyaviy maslahatchi'),d.sol)}</div><p>${keyLine}</p><p class="muted">${t('Zaxira')}: ${d.reserve.workersAi?'✅ Cloudflare Workers AI':'⚠️ Workers AI '+t('ulanmagan')} + ${t('ichki ma’lumotlar motori')}. ${t('OpenAI ishlamasa (kalit yo‘q, balans tugagan, limit), AI oynalari shu zaxira orqali javob beradi.')}</p><form class="form ai-key-form" id="aiKeyForm"><label>${t('Yangi OpenAI API kaliti')}<input name="key" type="password" autocomplete="off" spellcheck="false" placeholder="sk-..." required></label><div class="contact-phone-actions"><button class="primary" type="submit">${t('Tekshirish va saqlash')}</button>${key.stored.saved?`<button class="quiet" type="button" id="aiKeyRemove">${t('Saqlangan kalitni o‘chirish')}</button>`:''}</div><p class="muted">${t('Kalit shifrlangan holda saqlanadi va brauzerga qaytarilmaydi.')}</p><p class="form-message" role="status" id="aiKeyMsg"></p></form>`;
 const f=$('#aiKeyForm'),msg=m=>{$('#aiKeyMsg').textContent=m};
 f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button.primary');b.disabled=true;msg(t('Tekshirilmoqda…'));try{const r=await api('/api/admin/ai','POST',{action:'save',key:f.elements.key.value.trim()});f.reset();notify(t('Kalit saqlandi')+' …'+r.last4);aiAdmin(seq)}catch(err){msg(err.message);b.disabled=false}};
 if($('#aiKeyRemove'))$('#aiKeyRemove').onclick=async()=>{if(!confirm(t('Saqlangan kalit o‘chirilsinmi? Supabase secret’dagi kalit ishlatiladi.')))return;try{await api('/api/admin/ai','POST',{action:'remove'});aiAdmin(seq)}catch(err){msg(err.message)}}}
async function admin(seq){if(state.user?.role!=='admin'){page('Admin panel',empty('Ruxsat yo‘q','Bu bo‘lim faqat sayt administratoriga ochiq.'));return}page('Admin panel',`<p>Faqat haqiqiy yozuvlar. Yakunlangan buyurtma avtomatik ravishda to‘langan hisoblanmaydi.</p><div class="row-actions"><a class="primary" href="#/manage">Restoranlarni boshqarish →</a><a class="quiet" href="#/blog-admin">Blog boshqaruvi</a><a class="primary" href="/business-plan" target="_blank" rel="noopener">📄 ${t('Biznes-Reja (PDF)')}</a></div><section id="aiAdmin" class="panel ai-admin"></section><section id="telegramAdmin" class="panel telegram-admin"></section><section id="flowerAdmin" class="panel"></section><div class="panel"><label>HISOBOT DAVRI<select id="period"><option value="7">Oxirgi 7 kun</option><option selected value="30">Oxirgi 30 kun</option><option value="365">Oxirgi 365 kun</option><option value="all">Barcha vaqt</option></select></label></div><div id="adminReport"></div><section id="accountManagement" class="panel"></section>`);aiAdmin(seq);telegramAdmin(seq);api('/api/flowers?view=admin').then(f=>{if(seq!==state.seq||!$('#flowerAdmin'))return;$('#flowerAdmin').innerHTML=`<h3>💐 ${t('Gullar savdosi')}</h3><div class="metric-grid"><div class="metric"><small>${t('Sotuvlar')}</small><strong>${money(f.totals.sales)}</strong></div><div class="metric"><small>${t('Platforma komissiyasi')} (3%)</small><strong>${money(f.totals.commission)}</strong></div><div class="metric"><small>${t('Buyurtmalar')}</small><strong>${f.totals.count}</strong></div></div>${f.orders?.length?`<div class="table-wrap"><table><thead><tr><th>${t('Gul')}</th><th>${t('Gulchi')}</th><th>${t('Summa')}</th><th>3%</th><th>${t('Holat')}</th></tr></thead><tbody>${f.orders.map(o=>`<tr><td>${esc(o.title)} × ${o.quantity}</td><td>${esc(o.florist_name)}</td><td>${money(o.total)}</td><td>${money(o.commission)}</td><td>${esc(o.status)}${o.courier_name?' · 🛵 '+esc(o.courier_name):''}</td></tr>`).join('')}</tbody></table></div>`:''}`}).catch(()=>{});const report=async()=>{try{const d=await api('/api/admin?days='+$('#period').value);if(seq!==state.seq)return;const t=d.totals;$('#adminReport').innerHTML=`<div class="metric-grid"><div class="metric"><small>Tasdiqlangan to‘lovlar</small><strong>${money(t.gross)}</strong></div><div class="metric"><small>Qaytarishlar</small><strong>${money(t.refunds)}</strong></div><div class="metric"><small>Platforma komissiyasi</small><strong>${money(t.commission)}</strong></div></div><p class="notice">Onlayn to‘lov hali ulanmagan. Restoran sof foydasi uchun xarajatlar ham hisobga olinishi kerak.</p><div class="panel"><h3>Restoranlar kesimida</h3>${d.restaurants.length?`<div class="table-wrap"><table><thead><tr><th>Restoran</th><th>Holat</th><th>To‘lovlar</th><th>Qaytarish</th><th>Komissiya</th><th>Tushum</th></tr></thead><tbody>${d.restaurants.map(r=>`<tr><td>${esc(r.name)}</td><td>${statusName[r.status]||esc(r.status)}</td><td>${money(r.gross)}</td><td>${money(r.refunds)}</td><td>${money(r.commission)}</td><td>${money(r.gross-r.refunds-r.commission)}</td></tr>`).join('')}</tbody></table></div>`:'<p>Hali restoranlar qo‘shilmagan.</p>'}</div>`;await adminAccounts(seq)}catch(e){notify(e.message)}};$('#period').onchange=report;await report();}
// Subscription: 14-day Premium trial, then Start / Business / Premium. Online payment is not connected,
// so an administrator records the paid months after the restaurant pays.
const planFeatureNames={menu3d:'3D menyu (to‘liq ekran)',room3d:'3D zalda stol tanlab bron',adminAi:'Admin AI yordamchi (Business: kuniga 30 savol, bronlar va so‘rovlar; Premium: cheklovsiz)',liveTables:'AI kamera va jonli stol xaritasi',clientAi:'Mijozlar uchun ovozli 3D AI',visionTables:'O‘tirgan va turgan odamni farqlash, bandlik bron sahifasida',analytics:'Kengaytirilgan analitika',callAi:'Call AI: bronga 2 soat qolganda mijozga ovozli tasdiqlash qo‘ng‘irog‘i (Telegram)',peakDeposit:'Tig‘iz vaqt depoziti',tableMerge:'Stollarni birlashtirish',birthdayCrm:'Tug‘ilgan kun CRM va promokod',staffAccounts:'Xodimlar: Hostess, Ofitsiant, Menejer',aiReports:'AI haftalik analitika (Business: kuniga 1, Premium: cheksiz)',serviceTimer:'AI ofitsiant tezligi nazorati',vipGuests:'VIP mijoz dosyesi',happyHours:'Bo‘sh soatlarni to‘ldirish (avto chegirma)',tableView:'3D zalda stoldan ko‘rinish (panorama)'};
function renderPlanPanel(d){const host=$('#planPanel');if(!host)return;const r=d.restaurants.find(x=>x.id===$('#managedRestaurant').value);if(!r?.plan_state||!d.plans){host.hidden=true;for(const id of ['#liveMapPanel','#integrationPanel'])if($(id))$(id).hidden=true;return}host.hidden=false;const p=r.plan_state,admin=state.user?.role==='admin',until=p.status==='trial'?p.trialEndsAt:p.paidUntil;
 const status=p.status==='payment_required'?'Sinov muddati tugadi — to‘lov kerak. Hozir Start imkoniyatlari ishlaydi.':p.status==='active'&&p.daysLeft>3650?'Tarif faol (muddatsiz)':(p.status==='trial'?'Bepul Premium sinov':'Tarif faol')+': '+p.daysLeft+' '+t('kun qoldi');
 host.innerHTML=`<h3>Tarif</h3><p><a class="quiet" href="#/pricing">${t('Tariflarni solishtirish')} →</a></p><p class="${p.status==='payment_required'?'notice':''}"><b>${esc(status)}</b>${until&&p.status!=='payment_required'?` · ${esc(new Date(until).toLocaleDateString())}`:''}</p><div class="plan-grid">${Object.entries(d.plans).map(([id,plan])=>`<article class="plan-card ${p.plan===id?'chosen':''}"><h4>${esc(id[0].toUpperCase()+id.slice(1))}</h4><p class="plan-price">${money(plan.price)} <small>/ oy</small></p><ul>${plan.features.length?plan.features.map(f=>`<li>${esc(planFeatureNames[f]||f)}</li>`).join(''):'<li>Oddiy 2D menyu va ro‘yxatli bron</li>'}</ul>${p.plan===id?'<span class="badge">Tanlangan</span>':`<button type="button" class="quiet" data-plan-choose="${id}">Tanlash</button>`}</article>`).join('')}</div><p class="muted">To‘lov hozircha onlayn qabul qilinmaydi: tanlangan tarif uchun to‘lovni administrator tasdiqlaydi.</p>${admin?`<div class="two"><label>OYLAR<input id="planMonths" type="number" min="1" max="24" value="1"></label><button type="button" class="primary" id="planPaid">To‘lovni tasdiqlash</button></div>`:''}${p.features.visionTables?`<h4>Kamera (Vision AI)</h4><p>Kamera agenti stollar bandligini avtomatik yangilaydi. Kalit faqat bir marta ko‘rsatiladi.</p><button type="button" class="quiet" id="cameraKey">Kamera kalitini yaratish</button><pre id="cameraKeyOut" hidden></pre>`:''}`;
 const save=async body=>{try{const res=await api('/api/manage','POST',{action:'plan',restaurantId:r.id,...body});r.plan_state=res.plan_state;r.plan=body.plan;renderPlanPanel(d);notify('Tarif saqlandi.')}catch(e){notify(e.message)}};
 host.querySelectorAll('[data-plan-choose]').forEach(b=>b.onclick=()=>save({plan:b.dataset.planChoose}));
 if($('#planPaid'))$('#planPaid').onclick=()=>save({plan:p.plan,months:Number($('#planMonths').value)});
 if($('#cameraKey'))$('#cameraKey').onclick=async()=>{try{const res=await api('/api/manage','POST',{action:'camera_key',restaurantId:r.id,label:'Kamera'});const out=$('#cameraKeyOut');out.hidden=false;out.textContent='RF_CAMERA_KEY='+res.key+'\nRF_RESTAURANT_ID='+r.id+'\nRF_CAMERA_URL=rtsp://… node scripts/camera-agent.mjs'}catch(e){notify(e.message)}};;renderLiveMap(r);renderIntegrations(d,r);window.RFGrowth?.ownerPanel($('#growthPanel'),r.id);if(r.plan_state?.features?.serviceTimer)window.RFGrowth?.alerts($('#serviceAlerts'),r.id)
}
// Live table map (React, from the RF3D bundle): green free, red occupied, yellow booked; staff can override.
