function watchBookingStatus(scope,seq,onChange){clearInterval(bookingWatch);let known=null;const tick=async()=>{if(seq!==state.seq){clearInterval(bookingWatch);return}if(document.hidden)return;try{const rows=(await api('/api/bookings/status'))[scope]||[];if(seq!==state.seq)return;const next=new Map(rows.map(r=>[r.id,r.status+'|'+r.deposit_status]));const changes=known?rows.filter(r=>known.has(r.id)&&known.get(r.id)!==next.get(r.id)):[];known=next;if(changes.length)onChange(changes)}catch{}};tick();bookingWatch=setInterval(tick,8000)}
function stopBookingWatch(){clearInterval(bookingWatch);bookingWatch=0}
