function drawerIcon(id){const p={pricing:'<path d="M20 12 12 20 3 11V3h8z"/><circle cx="7.5" cy="7.5" r="1.5"/>',flowers:'<circle cx="12" cy="8" r="3"/><path d="M12 5a3 3 0 0 1 3-3M12 5a3 3 0 0 0-3-3M9 8a3 3 0 0 1-3-3M15 8a3 3 0 0 0 3-3M12 11v11M12 17c-2-2-5-2-6-1M12 15c2-2 5-2 6-1"/>',florist:'<path d="M4 21h16M6 21V11l6-5 6 5v10"/><circle cx="12" cy="14" r="2"/>',discover:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3z"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',cart:'<path d="M2 3h3l3 13h11l3-9H6"/><circle cx="9" cy="21" r="1"/><circle cx="19" cy="21" r="1"/>',bookings:'<rect x="3" y="4" width="18" height="17" rx="3"/><path d="M8 2v4M16 2v4M3 10h18"/>',orders:'<path d="M6 2h12l2 5v13a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V7z"/><path d="M4 7h16M9 12h6"/>',billing:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M2 10h20M6 15h4"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.8l.1.1a2 2 0 1 1-2.8 2.8l-.1-.1a1.7 1.7 0 0 0-1.8-.3 1.7 1.7 0 0 0-1 1.5V21a2 2 0 1 1-4 0v-.1a1.7 1.7 0 0 0-1.1-1.5 1.7 1.7 0 0 0-1.8.3l-.1.1a2 2 0 1 1-2.8-2.8l.1-.1a1.7 1.7 0 0 0 .3-1.8 1.7 1.7 0 0 0-1.5-1H3a2 2 0 1 1 0-4h.1a1.7 1.7 0 0 0 1.5-1.1 1.7 1.7 0 0 0-.3-1.8l-.1-.1a2 2 0 1 1 2.8-2.8l.1.1a1.7 1.7 0 0 0 1.8.3H9a1.7 1.7 0 0 0 1-1.5V3a2 2 0 1 1 4 0v.1a1.7 1.7 0 0 0 1 1.5 1.7 1.7 0 0 0 1.8-.3l.1-.1a2 2 0 1 1 2.8 2.8l-.1.1a1.7 1.7 0 0 0-.3 1.8V9a1.7 1.7 0 0 0 1.5 1H21a2 2 0 1 1 0 4h-.1a1.7 1.7 0 0 0-1.5 1z"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 3.5 2.3c-.6.3-1 .9-1 1.7M12 17h.01"/>',manage:'<path d="M3 21h18M5 21V8l7-5 7 5v13M9 21v-6h6v6"/>',camera:'<path d="M3 7h4l2-3h6l2 3h4v13H3z"/><circle cx="12" cy="13" r="4"/>',admin:'<path d="M12 2 4 5v6c0 5 3.4 9.4 8 11 4.6-1.6 8-6 8-11V5z"/>',courier:'<circle cx="6" cy="17" r="3"/><circle cx="18" cy="17" r="3"/><path d="M9 17h6l-3-8h4l2 5M5 9h4"/>'}[id]||'<circle cx="12" cy="12" r="8"/>';return `<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${p}</svg>`}
// Opens the menu as a side drawer (desktop) or a bottom sheet (phones), growing out of the button pressed.
function openDrawer(origin){const d=$('#drawer');if(d.open)return;d.showModal();window.RFMotion?.open(d,origin);window.RFMotion?.swipe(d,closeDrawer);$('#menuButton').setAttribute('aria-expanded','true');document.querySelector('.mobile-more')?.setAttribute('aria-expanded','true')}
function mobileNavigation(){const root=$('#mobileNav');if(!root)return;root.hidden=false;const count=readCart()?.items.reduce((s,i)=>s+i.quantity,0)||0;const feedbackCount=document.querySelector('[data-feedback-cart-count]');if(feedbackCount){feedbackCount.textContent=String(count);feedbackCount.hidden=!count}root.innerHTML=[['discover','⌂','Bosh sahifa'],['search','⌕','Qidiruv'],['cart','▣','Savat'],['account','♙','Profil']].map(([id,icon,label])=>`<a href="#/${id}" ${routeName()===id?'aria-current="page"':''}><span aria-hidden="true">${navIcon(id)}</span>${esc(t(label))}${id==='cart'&&count?`<b>${count}</b>`:''}</a>`).join('')+`<button type="button" class="mobile-more" aria-haspopup="dialog" ${$('#drawer').open?'aria-expanded="true"':''}><span aria-hidden="true"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/></svg></span>${esc(t('Ko‘proq'))}</button>`;root.querySelector('.mobile-more').onclick=e=>openDrawer(e.currentTarget)}
function bindMenuCart(r,menu){
 const form=$('#orderForm');if(!form)return;
 form.querySelector('.form').innerHTML='<div class="menu-cart-actions"><a class="primary" href="#/cart">Savatga o‘tish →</a><button type="button" class="quiet" data-cart-sound aria-pressed="true"></button></div>';
 window.RFCartFX?.bindSound(form.querySelector('[data-cart-sound]'));
 const update=()=>{const cart=readCart(),items=cart?.restaurantId===r.id?cart.items:[];$('#orderTotal').textContent=t('Taomlar')+': '+money(items.reduce((sum,i)=>sum+(menu.find(m=>m.id===i.id)?.price||0)*i.quantity,0));const badge=form.querySelector('[data-menu-cart-count]');if(badge)badge.textContent=(cart?.items||[]).reduce((n,i)=>n+i.quantity,0)};
 // Menu quantities are drafts. Only the explicit Add button commits a dish.
 form.oninput=e=>{if(e.target.matches?.('input.qty'))e.target.setCustomValidity('')};
 form.querySelectorAll('[data-menu-add]').forEach(button=>button.onclick=()=>{
  const dish=menu.find(m=>m.id===button.dataset.menuAdd),input=form.elements.namedItem(button.dataset.menuAdd),quantity=Number(input?.value);
  if(!dish?.available||!input||input.disabled)return;
  input.setCustomValidity('');
  if(!Number.isInteger(quantity)||quantity<1||quantity>20){input.setCustomValidity(t('1 dan 20 tagacha tanlang.'));input.reportValidity();return}
  const cart=readCart(),sameRestaurant=cart?.restaurantId===r.id,items=sameRestaurant?cart.items.map(i=>({...i})):[],existing=items.find(i=>i.id===dish.id);
  if((existing?.quantity||0)+quantity>20){input.setCustomValidity(t('Savatda bir taomdan ko‘pi bilan 20 ta bo‘lishi mumkin.'));input.reportValidity();return}
  window.RFCartFX?.arm();
  if(cart?.items.length&&!sameRestaurant&&!confirm(t('Boshqa restoran tanlandi. Avvalgi savat almashtirilsinmi?')))return;
  if(existing)existing.quantity+=quantity;else items.push({id:dish.id,quantity});
  state.cart={restaurantId:r.id,items,fulfillment:(state.selectedFulfillment==='delivery'||catalogFilter.service==='delivery')&&r.delivery_enabled?'delivery':sameRestaurant?cart.fulfillment:'pickup'};
  saveCart();update();window.RFCartFX?.add(button)
 });
 form.onsubmit=e=>{e.preventDefault();location.hash='/cart'};update()
}
function cartQuote(cart,menu,r){const items=cart.items.map(i=>{const m=menu.find(m=>m.id===i.id&&m.restaurant_id===r.id&&m.available);return m?{...i,name:m.name,price:m.price}:null}),invalid=items.some(i=>!i),valid=items.filter(Boolean),subtotal=valid.reduce((s,i)=>s+i.price*i.quantity,0),fee=cart.fulfillment==='delivery'?Number(r.delivery_fee)||0:0;return {items:valid,invalid,subtotal,fee,total:subtotal+fee}}
async function cartPage(seq){await loadCatalog();if(seq!==state.seq)return;const cart=readCart(),r=state.catalog.find(r=>r.id===cart?.restaurantId);if(!cart?.items.length||!r){page('Savat',empty('Savat bo‘sh','Restoran menyusidan taom tanlang.')+'<a class="primary" href="#/discover">Restoranlar</a>');return}const q=cartQuote(cart,state.menu,r);page('Savat',`<section class="panel compact"><h2>${esc(r.name)}</h2>${r.id.startsWith('rf-demo-')?'<p class="notice">DEMO: haqiqiy xizmat ko‘rsatilmaydi. Buyurtma va bronlar faqat sinov uchun.</p>':''}<a class="link" href="#/restaurant/${encodeURIComponent(r.id)}">Menyuga qaytish</a>${q.invalid?'<p class="notice">Ayrim taomlar mavjud emas. Ular savatdan olib tashlandi.</p>':''}<div class="rows">${q.items.map(i=>`<div class="row"><div><strong>${esc(i.name)}</strong><p>${money(i.price)} × ${i.quantity}</p></div><label>Soni<input class="qty" type="number" min="0" max="20" value="${i.quantity}" data-cart-qty="${esc(i.id)}" aria-label="${esc(i.name)}"></label><button class="link" data-cart-remove="${esc(i.id)}">O‘chirish</button></div>`).join('')}</div><form id="checkoutForm" class="form"><label>BUYURTMA TURI<select id="cartFulfillment"><option value="pickup">Olib ketish</option>${r.delivery_enabled?'<option value="delivery">Yetkazib berish</option>':''}</select></label><div id="cartSummary" aria-live="polite"></div><label>TELEFON<input name="phone" type="tel" value="${esc(state.user?.contactPhone||state.user?.phone||'')}" pattern="\\+998[0-9]{9}" placeholder="+998901234567" required></label><div id="cartDelivery" class="form" hidden>${coordinateFields('cart')}<label>UY, PODYEZD, MO‘LJAL (IXTIYORIY)<input id="cartAddress" maxlength="300" value="${esc(state.user?.address||'')}" placeholder="${esc(t('Masalan: 12-uy, 3-podyezd, 45-xonadon'))}"></label></div><p>Buyurtma restoran tasdig‘ini kutadi. To‘lov qabul qilish vaqtida.</p>${state.user?`<button class="primary" id="placeOrder">${r.is_demo?t('Demo buyurtmani sinash'):t('Buyurtma yuborish')}</button>`:'<a class="primary" href="#/login">Buyurtma uchun kiring</a>'}<p id="cartMessage" role="status"></p></form></section>`);cart.items=q.items.map(({id,quantity})=>({id,quantity}));if(!r.delivery_enabled)cart.fulfillment='pickup';saveCart();if(!cart.items.length){await cartPage(seq);return}$('#cartFulfillment').value=cart.fulfillment;const summary=()=>{cart.fulfillment=$('#cartFulfillment').value;saveCart();const v=cartQuote(cart,state.menu,r);$('#cartSummary').innerHTML=`<div class="row"><span>Taomlar</span><strong>${money(v.subtotal)}</strong></div><div class="row"><span>Yetkazib berish</span><strong>${money(v.fee)}</strong></div><div class="row"><span>Xizmat haqi</span><strong>${money(0)}</strong></div><div class="row"><strong>Jami</strong><strong>${money(v.total)}</strong></div>`;$('#cartDelivery').hidden=cart.fulfillment!=='delivery';};summary();$('#cartFulfillment').onchange=summary;bindCoordinateButtons();document.querySelectorAll('[data-cart-qty]').forEach(input=>input.onchange=()=>{const n=Number(input.value);if(!Number.isInteger(n)||n<0||n>20){input.reportValidity();return}cart.items=cart.items.map(i=>i.id===input.dataset.cartQty?{...i,quantity:n}:i).filter(i=>i.quantity);saveCart();cartPage(seq)});document.querySelectorAll('[data-cart-remove]').forEach(b=>b.onclick=()=>{cart.items=cart.items.filter(i=>i.id!==b.dataset.cartRemove);saveCart();cartPage(seq)});$('#checkoutForm').onsubmit=async e=>{e.preventDefault();if(!state.user){location.hash='/login';return}if(r.is_demo||r.id.startsWith('rf-demo-')){const receipt=cartQuote(cart,state.menu,r);state.cart=null;localStorage.removeItem('rf-cart');page('Demo buyurtma',`<section class="panel compact"><span class="demo-badge">DEMO</span><h2>${esc(r.name)}</h2><p>${t('Demo savat tekshirildi. Restoranga haqiqiy buyurtma yoki to‘lov yuborilmadi.')}</p>${receipt.items.map(i=>`<p>${esc(i.name)} × ${i.quantity} — ${money(i.price*i.quantity)}</p>`).join('')}<strong>${t('Jami')}: ${money(receipt.total)}</strong><p><a class="primary" href="#/discover">${t('Restoranlar')}</a></p></section>`);mobileNavigation();return}const button=$('#placeOrder');button.disabled=true;try{const result=await api('/api/orders','POST',{restaurantId:r.id,items:cart.items,phone:e.currentTarget.elements.phone.value,fulfillment:cart.fulfillment,deliveryAddress:$('#cartAddress').value,deliveryLat:readCoord('cartLat'),deliveryLng:readCoord('cartLng')});state.cart=null;try{localStorage.removeItem('rf-cart')}catch{}notify('Buyurtma yuborildi: '+money(result.total));location.hash='/tracking/'+encodeURIComponent(result.id)}catch(err){$('#cartMessage').textContent=err.message;button.disabled=false}}}
// Same rule as the API (booking-rules.ts): customers cancel until 2 hours before the start (Tashkent time).
function bookingCancellable(b,now=Date.now()){return Date.parse(b.date+'T'+String(b.slot).slice(0,5)+':00+05:00')-now>=2*3600000}
function deliveryHeadline(o){if(o.status==='cancelled')return '';const eta=o.eta_minutes,at=eta?new Date(Date.now()+eta*60000).toLocaleTimeString(RF_I18N.locale(),{hour:'2-digit',minute:'2-digit'}):'';const delivery=o.fulfillment==='delivery',name=o.courier_name?esc(o.courier_name):t('Kuryer');
 const title=o.status==='completed'?(delivery?'✅ '+t('Yetkazildi. Yoqimli ishtaha!'):'✅ '+t('Yakunlangan')):o.status==='pending'?'⏳ '+t('Restoran buyurtmani tasdiqlashi kutilmoqda'):!delivery?'👨‍🍳 '+t('Tayyorlanmoqda'):o.delivery_status==='picked_up'?'🛵 '+name+' '+t('yo‘lda'):o.delivery_status==='assigned'?'👨‍🍳 '+t('Tayyorlanmoqda')+' · '+name+' '+t('taomni oladi'):'👨‍🍳 '+t('Tayyorlanmoqda');
 return `<div class="delivery-headline"><strong>${title}</strong>${eta?`<span class="delivery-eta">≈ ${eta} ${t('daqiqa')} · ${t('taxminan')} ${esc(at)}</span>`:''}${delivery&&o.courier_phone&&o.status==='confirmed'&&o.delivery_status!=='unassigned'?`<a class="quiet" href="tel:${esc(o.courier_phone)}">📞 ${t('Kuryerga qo‘ng‘iroq')}</a>`:''}</div>`}
function orderProgress(o){if(o.status==='cancelled')return '<p class="notice">Bekor qilingan</p>';const delivery=o.fulfillment==='delivery',steps=['Qabul qilindi','Tayyorlanmoqda',delivery?'Kuryerda':'Olib ketishga tayyor',delivery?'Yetkazildi':'Yakunlangan'];if(!delivery)steps.splice(2,1);const current=o.status==='completed'?steps.length-1:o.delivery_status==='picked_up'?2:o.status==='confirmed'?1:0;return `<ol class="order-progress" style="grid-template-columns:repeat(${steps.length},1fr)">${steps.map((step,i)=>`<li class="${i<=current?'done':''}" ${i===current?'aria-current="step"':''}><span>${i<current?'✓':i+1}</span>${esc(t(step))}</li>`).join('')}</ol>${o.status==='pending'?'<small>Restoran tasdig‘i kutilmoqda.</small>':''}`}

function navIcon(id){const paths={discover:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3Z"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>',cart:'<path d="M2 3h3l3 13h11l3-9H6"/><circle cx="9" cy="21" r="1"/><circle cx="19" cy="21" r="1"/>',account:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>'};return `<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${paths[id]||''}</svg>`}

async function blogAdmin(seq){if(state.user?.role!=='admin'){page('Blog boshqaruvi',empty('Ruxsat yo‘q','Bu bo‘lim faqat sayt administratoriga ochiq.'));return}const d=await api('/api/blog');if(seq!==state.seq)return;page('Blog boshqaruvi',`<a href="#/admin">← Admin panel</a><section class="panel"><label>${t('Maqola tanlang')}<select id="blogSelect"><option value="">${t('Yangi maqola')}</option>${d.posts.map(p=>`<option value="${esc(p.id)}">${esc(p.lang+' · '+p.title+' · '+p.status)}</option>`).join('')}</select></label><div id="blogEditor"></div></section>`);const editor=()=>{const p=d.posts.find(p=>p.id===$('#blogSelect').value);$('#blogEditor').innerHTML=`<form id="blogForm" class="form"><label>${t('Sarlavha')}<input name="title" maxlength="160" minlength="5" required value="${esc(p?.title||'')}"></label><label>URL slug<input name="slug" pattern="[a-z0-9]+(-[a-z0-9]+)*" minlength="3" maxlength="100" required value="${esc(p?.slug||'')}"></label><p>${t('Tarjimalar uchun bir xil slug ishlating.')}</p><label>${t('Sayt tili')}<select name="lang">${['ru','uz','en'].map(l=>`<option ${l===(p?.lang||RF_I18N.lang)?'selected':''}>${l}</option>`).join('')}</select></label><label>${t('Qisqa tavsif')}<textarea name="description" minlength="20" maxlength="320" required>${esc(p?.description||'')}</textarea></label><label>${t('Maqola matni')}<textarea name="content" rows="18" minlength="100" maxlength="12000" required>${esc(p?.content||'')}</textarea></label><p>${t('Bo‘lim sarlavhasini ## bilan boshlang. Abzaslarni bo‘sh qator bilan ajrating. HTML ishlatilmaydi.')}</p><label>${t('Holat')}<select name="status"><option value="draft" ${p?.status!=='published'?'selected':''}>${t('Qoralama')}</option><option value="published" ${p?.status==='published'?'selected':''}>${t('Nashr qilingan')}</option></select></label><div class="row-actions"><button class="primary">${t('Maqolani saqlash')}</button>${p?`<button type="button" class="quiet" id="deleteBlog">${t('O‘chirish')}</button>${p.status==='published'?`<a href="#/help/blog/${esc(p.slug)}">${t('Ko‘rish')} →</a>`:''}`:''}</div><p id="blogMessage" role="status"></p></form>`;$('#blogForm').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;try{await api('/api/blog','POST',{...Object.fromEntries(new FormData(e.currentTarget)),id:p?.id});notify('Saqlandi');render()}catch(e){$('#blogMessage').textContent=e.message;button.disabled=false}};if($('#deleteBlog'))$('#deleteBlog').onclick=async()=>{if(!confirm(t('Maqola o‘chirilsinmi?')))return;try{await api('/api/blog','POST',{action:'delete',id:p.id});render()}catch(e){notify(e.message)}}};$('#blogSelect').onchange=editor;editor()}

async function helpCenter(seq){
 const route=routeName(),parts=location.hash.replace(/^#\/?/,'').split('/'),tab=route==='support'?'contact':route==='faq'?'faq':route==='blog'?'blog':['faq','blog','contact'].includes(parts[1])?parts[1]:'faq',slug=route==='blog'?parts[1]:parts[2];
 const tabs=`<nav class="help-tabs" aria-label="${t('Yordam markazi')}">${[['faq','Savol va javoblar'],['blog','Blog maqolalari'],['contact','Aloqa']].map(([id,label])=>`<a class="quiet ${tab===id?'selected':''}" href="#/help/${id}" ${tab===id?'aria-current="page"':''}>${t(label)}</a>`).join('')}</nav>`;
 const shell=body=>page('Yordam markazi',`<section class="help-center"><p class="help-intro">${t('Savollarga javoblar, foydali maqolalar va biz bilan aloqa — bir joyda.')}</p>${tabs}${body}</section>`);
 if(tab==='contact'){shell(`<div class="two"><section class="panel"><p class="eyebrow">${t('TELEFON')}</p><h2 class="contact-detail">+998 99 384 73 84</h2><a class="primary" href="tel:+998993847384">${t('Qo‘ng‘iroq qilish')}</a></section><section class="panel"><p class="eyebrow">EMAIL</p><h2 class="contact-detail">admin@restaurantfoods.online</h2><a class="primary" href="mailto:admin@restaurantfoods.online?subject=RestaurantFoods%20Support">${t('Email yozish')}</a></section></div><section class="panel"><h3>${t('Murojaatingizda nimalarni yozish kerak?')}</h3><p>${t('Restoran nomi, bron yoki buyurtma sanasi va muammo tavsifini kiriting. Parol va tasdiqlash kodlarini yubormang.')}</p></section>`);return}
 shell(`<p role="status">${t('Yuklanmoqda…')}</p>`);
 const data=await api('/api/info?lang='+encodeURIComponent(RF_I18N.lang)+(tab==='blog'?'&section=blog'+(slug?'&slug='+encodeURIComponent(slug):''):''));if(seq!==state.seq)return;
 if(tab==='faq'){shell(`<div class="help-faq">${data.faqs.map(([question,answer])=>`<details class="panel"><summary>${esc(question)}<span aria-hidden="true">＋</span></summary><p>${esc(answer)}</p></details>`).join('')}</div>`);return}
 if(slug){const post=data.post;if(!post){shell(empty('Maqola topilmadi.','')+`<a class="quiet" href="#/help/blog">← ${t('Blog maqolalari')}</a>`);return}shell(`<article class="panel help-article"><a class="link" href="#/help/blog">← ${t('Blog maqolalari')}</a><h2>${esc(post.title)}</h2><p>${esc(post.description)}</p><div class="separator"></div>${post.content.split(/\n\s*\n/).map(p=>p.startsWith('## ')?`<h3>${esc(p.slice(3))}</h3>`:`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join('')}</article>`);return}
 shell(data.posts.length?`<div class="help-posts">${data.posts.map(post=>`<a class="panel help-post" href="#/help/blog/${encodeURIComponent(post.slug)}"><span class="eyebrow">${t('Blog maqolalari')}</span><h2>${esc(post.title)}</h2><p>${esc(post.description)}</p><span class="link">${t('O‘qish')} →</span></a>`).join('')}</div>`:empty('Maqolalar hali e’lon qilinmagan.',''))
}
// Boot last, so no top-level let/const is touched before it is initialised.
(async()=>{setInterval(()=>{if(state.user&&document.visibilityState==='visible')renewSession()},45*60*1000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state.user)renewSession()});try{document.body.dataset.theme=localStorage.getItem('rf-theme')||'dark'}catch{}
// One first render, after the session and language are known (the splash covers the wait); a slow network
// still gets the guest screen after 4 s and the signed-in one when the session arrives.
let slowBoot=setTimeout(()=>{slowBoot=0;render().finally(bootDone)},4000);try{const [config,me]=await Promise.all([api('/api/auth/config'),api('/api/me')]);state.config=config;state.user=me.user;if(!state.user&&await renewSession())state.user=(await api('/api/me')).user;if(state.user&&!location.hash){const after=sessionStorage.getItem('rf-after-login');if(after&&/^#\/(restaurant\/|cart$|bookings$|discover$)/.test(after)){sessionStorage.removeItem('rf-after-login');location.hash=after}}if(state.user&&!requestedLanguage)RF_I18N.set(state.user.preferredLanguage||'ru')}catch(e){notify(e.message)}if(slowBoot)clearTimeout(slowBoot);try{await render()}finally{bootDone()}})();
